import { Suspense } from 'react'
import { RequestMetadata } from '@/components/request-metadata'

export default function RootLayout({ children }: { children: ReactNode }) {
  return (
    <html lang="en">
      <body>
        <nav>Operations</nav>
        <Suspense fallback={<aside>Loading request metadata</aside>}>
          <RequestMetadata />
        </Suspense>
        {children}
      </body>
    </html>
  )
}

